#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <sys/syscall.h>

// WARNING: The sysfs(2) syscall is obsolete and lacks a standard glibc wrapper.
// The syscall number (__NR_sysfs) is architecture-dependent and may not exist.
// We use direct syscall() for demonstration.

#ifndef __NR_sysfs
    // Using a common historical number; adjust if compiling for a specific architecture
    #define __NR_sysfs 84 
#endif

// Helper to call sysfs(option, arg2, arg3)
long custom_sysfs(int option, long arg2, long arg3) {
    return syscall(__NR_sysfs, option, arg2, arg3);
}

int main() {
    long result;

    // --- Option 3: Get total count of filesystem types ---
    printf("Querying total filesystem count (Option 3)...\n");

    // sysfs(3)
    result = custom_sysfs(3, 0, 0);

    if (result == -1) {
        if (errno == ENOSYS) {
             fprintf(stderr, "Error: sysfs() is not implemented or unavailable on this kernel.\n");
        } else {
             perror("Error calling sysfs(3)");
        }
        // Continue to Option 1 demonstration even if Option 3 fails
    } else {
        printf("Total number of filesystem types: %ld\n\n", result);
    }

    // --- Option 1: Translate fsname ("ext4") into an index ---
    const char *fs_name = "ext4";
    printf("Translating '%s' into an index (Option 1)...\n", fs_name);

    // sysfs(1, fs_name)
    // Note: fs_name is passed as the second argument (arg2)
    result = custom_sysfs(1, (long)fs_name, 0);

    if (result == -1) {
        if (errno == EINVAL) {
            fprintf(stderr, "Error: Filesystem '%s' not found or invalid input (%s).\n", fs_name, strerror(errno));
        } else {
            perror("Error calling sysfs(1)");
        }
    } else {
        printf("Filesystem '%s' index: %ld\n", fs_name, result);
    }

    return EXIT_SUCCESS;
}
